algorithms.pseudocode:
function VALLEY(s):        return (s * ln 2)^(1/s)
function VALLEY-FLOOR(s):  u <- s * ln 2 ; return (1 + ln u)/u   # always <= 1

function CROSSINGS(level, s):
    require level > VALLEY-FLOOR(s)          # else the level misses the curve
    v <- VALLEY(s)
    f(n) <- log2(n) + n^(-s) - level
    df(n) <- 1/(n ln 2) - s * n^(-s-1)
    lo <- v ; while f(lo) < 0: lo <- lo / 2   # bracket the left root
    left <- NEWTON(f, df, BISECT(f, lo, v))
    hi <- v ; while f(hi) < 0: hi <- hi * 2   # bracket the right root
    right <- NEWTON(f, df, BISECT(f, v, hi))
    return (left, right)

function CROSSING-FOR-PACKET(b, s):
    return second component of CROSSINGS(b + 1, s)   # approaches 2^(b+1)

algorithms.code:
"""Unimodal crossing locator for generalised fork channels.

Generalisation.  Let the exchange channel carry a b-bit packet and let the
entropy deficit be delta_s(n) = n^(-s).  Then

    A(n)  = log2(n) - 1 - n^(-s),
    X(n)  = b (1 - n^(-s)),
    A - X = R_s(n) - (b + 1),      R_s(n) = log2(n) + n^(-s).

So every such model is governed by the same unimodal functional R_s at the
critical level c = b + 1.  R_s has a single valley at n^s = s ln 2, with floor

    R_s^min = (1 + ln u) / u,      u = s ln 2,

whose maximum over all s > 0 is exactly 1 (at u = 1, i.e. s = 1/ln 2).  Hence
for any critical level c > 1 the equation R_s(n) = c has exactly two solutions,
one on each side of the valley.  This routine returns both, using bisection to
isolate them and Newton's method (quadratically convergent, since
R_s'(n) = 1/(n ln 2) - s n^(-s-1) does not vanish away from the valley) to
polish them.
"""

from __future__ import annotations

from math import log, log2
from typing import Tuple

LN2: float = log(2.0)


def resonance(n: float, s: float = 2.0) -> float:
    """R_s(n) = log2(n) + n^(-s)."""
    return log2(n) + n ** (-s)


def resonance_derivative(n: float, s: float = 2.0) -> float:
    """R_s'(n) = 1/(n ln 2) - s n^(-s-1)."""
    return 1.0 / (n * LN2) - s * n ** (-s - 1.0)


def valley(s: float = 2.0) -> float:
    """The unique minimiser of R_s: n^s = s ln 2."""
    return (s * LN2) ** (1.0 / s)


def valley_floor(s: float = 2.0) -> float:
    """R_s at its valley: (1 + ln u)/u with u = s ln 2.  Never exceeds 1."""
    u = s * LN2
    return (1.0 + log(u)) / u


def _bisect(f, lo: float, hi: float, iters: int = 100) -> float:
    """Bisection for f with opposite signs at the endpoints."""
    flo = f(lo)
    for _ in range(iters):
        mid = 0.5 * (lo + hi)
        if (f(mid) < 0.0) == (flo < 0.0):
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def _newton(f, df, x: float, steps: int = 40) -> float:
    for _ in range(steps):
        d = df(x)
        if d == 0.0:
            break
        step = f(x) / d
        x -= step
        if abs(step) < 1e-15 * max(1.0, abs(x)):
            break
    return x


def crossings(level: float = 3.0, s: float = 2.0) -> Tuple[float, float]:
    """Both solutions of R_s(n) = level (they exist whenever level > R_s^min)."""
    if level <= valley_floor(s):
        raise ValueError("level does not clear the valley floor")
    v = valley(s)

    def f(n: float) -> float:
        return resonance(n, s) - level

    def df(n: float) -> float:
        return resonance_derivative(n, s)

    lo = v
    while f(lo) < 0.0:
        lo *= 0.5
    left = _newton(f, df, _bisect(f, lo, v))

    hi = v
    while f(hi) < 0.0:
        hi *= 2.0
    right = _newton(f, df, _bisect(f, v, hi))
    return left, right


def crossing_for_packet(bits: int, s: float = 2.0) -> float:
    """Super-critical crossing arity for a b-bit exchange packet."""
    return crossings(level=float(bits) + 1.0, s=s)[1]


if __name__ == "__main__":
    print(f"valley of R_2 at n* = {valley():.9f}, floor = {valley_floor():.9f}")
    left, right = crossings()
    print(f"crossings of R_2 at level 3: {left:.12f} and {right:.12f}")
    print()
    print("crossing arity as a function of the exchange packet width b:")
    for b in range(1, 9):
        print(f"  b = {b} bits -> critical level {b + 1}, "
              f"crossing arity {crossing_for_packet(b):.6f}")
